// CONFIGURACIÓN de este cliente. Es lo único que se edita en este flujo.
// - orgId y llave: Admin de Reymen → Clientes → (cliente) → botón de webhook ("ID de organización" y "llave de conexión").
//   La llave es secreta: este flujo queda guardado en tu n8n; no lo exportes ni lo compartas con la llave puesta.
// - Twilio: el Account SID está en la consola de Twilio; el token va en la credencial "Twilio" de n8n (no aquí).
// - contentSid: plantilla de WhatsApp APROBADA en Twilio (Content Template Builder). WhatsApp exige plantilla para escribirle
//   a alguien que no te ha escrito en las últimas 24 h, que es el caso normal de un seguimiento. Si se deja vacío, se manda el
//   texto de la regla de Reymen, que solo entrega dentro de esas 24 h.
// - modoPrueba: true = solo arma los mensajes y los muestra, sin enviar ni avisar a Reymen. Ponlo en false cuando todo esté bien.
return [{ json: {
  reymenUrl: 'https://app.reymen.mx',
  orgId: 'PEGA_AQUI_EL_ID_DE_LA_ORGANIZACION',
  llave: 'PEGA_AQUI_LA_LLAVE_DE_CONEXION',
  twilioAccountSid: 'ACxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx',
  whatsappFrom: '+528100000000', // tu número de WhatsApp en Twilio, con +52
  contentSid: '',
  horaInicio: 9,
  horaFin: 20,
  zonaHoraria: 'America/Monterrey',
  maxPorCorrida: 40,
  modoPrueba: true,
} }];

// Toma los seguimientos que Reymen dice que ya tocan y arma un mensaje de WhatsApp por persona.
// Reymen ya filtró: estado del contacto, tiempo de espera, intentos máximos y "no contactar".
const cfg = $('Configuración').first().json;
const rows = ($input.first().json.data || []);

// Solo en horario del negocio, para no escribir de madrugada.
const hora = Number(new Intl.DateTimeFormat('es-MX', { hour: 'numeric', hour12: false, timeZone: cfg.zonaHoraria }).format(new Date()));
if (hora < cfg.horaInicio || hora >= cfg.horaFin) return [];

// Teléfono a formato internacional de México (+52 + 10 dígitos). Si no se puede, se omite (se reintenta en la próxima corrida).
function e164(raw) {
  const d = String(raw || '').replace(/\D/g, '');
  if (d.length === 10) return '+52' + d;
  if (d.length === 12 && d.startsWith('52')) return '+' + d;
  if (d.length === 13 && d.startsWith('521')) return '+52' + d.slice(3);
  return null;
}
const nombre = (n) => String(n || '').trim().split(/\s+/)[0] || '';

const out = [];
for (const r of rows) {
  if (r.channel !== 'whatsapp') continue;
  const to = e164(r.contactPhone);
  if (!to) continue;
  const text = String(r.template || '').replace(/\{\{\s*contactName\s*\}\}/g, nombre(r.contactName)).trim();
  const form = new URLSearchParams({ From: 'whatsapp:' + cfg.whatsappFrom, To: 'whatsapp:' + to });
  if (cfg.contentSid) {
    form.set('ContentSid', cfg.contentSid);
    form.set('ContentVariables', JSON.stringify({ 1: nombre(r.contactName) || 'hola' }));
  } else {
    form.set('Body', text);
  }
  out.push({ json: {
    leadId: r.leadId, ruleId: r.ruleId, attemptNumber: r.attemptNumber,
    contacto: r.contactName, to, text, form: form.toString(),
    twilioUrl: 'https://api.twilio.com/2010-04-01/Accounts/' + cfg.twilioAccountSid + '/Messages.json',
    modoPrueba: cfg.modoPrueba === true,
  } });
  if (out.length >= cfg.maxPorCorrida) break;
}
return out;

// Para cada mensaje que Twilio aceptó (trae "sid"), arma el aviso firmado para que Reymen cuente el intento.
// Los que fallaron no se avisan: Reymen los vuelve a ofrecer en la próxima corrida.
// Requiere NODE_FUNCTION_ALLOW_BUILTIN=crypto en el entorno de n8n (el mismo que ya usan los demás flujos de Reymen).
const crypto = require('crypto');
const cfg = $('Configuración').first().json;
const enviados = $('Preparar mensajes').all();
const out = [];
$input.all().forEach((res, i) => {
  const sent = enviados[i] && enviados[i].json;
  if (!sent || !res.json.sid) return;
  const body = JSON.stringify({ leadId: sent.leadId, ruleId: sent.ruleId });
  const ts = String(Date.now());
  const sig = 'sha256=' + crypto.createHmac('sha256', cfg.llave).update(ts + '.' + body).digest('hex');
  out.push({ json: {
    url: cfg.reymenUrl + '/api/webhooks/n8n/followup-sent',
    orgId: cfg.orgId, body, ts, sig,
    // Id estable por intento: si este aviso se repite, Reymen lo cuenta una sola vez.
    eventId: 'followup:' + sent.leadId + ':' + sent.ruleId + ':' + sent.attemptNumber,
    contacto: sent.contacto, twilioSid: res.json.sid,
  } });
});
return out;
